WITH filtered AS (SELECT *, ROUND(quantity * 0.85, 2) AS adjusted_quantity, LAST_DAY(last_restock) AS last_restock_month_end FROM inventory WHERE last_restock > TO_DATE('2023-07-24')), with_dims AS (SELECT src.*, p.category, p.stock_qty FROM filtered src LEFT JOIN products p ON src.product_id = p.id), latest AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY category ORDER BY quantity, id) AS dedup_rank FROM with_dims) x WHERE dedup_rank = 1), deduped AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY category ORDER BY stock_qty DESC, id) AS dedup_rank_2 FROM latest) ranked WHERE dedup_rank_2 = 1) SELECT id, store_id, product_id, last_restock, adjusted_quantity, stock_qty, dedup_rank_2 FROM deduped ORDER BY id DESC NULLS LAST
